#pragma once
// The named retail structs (docs/RETAIL_LAYOUTS.md) as field lists, for the debug UI's object inspector. The list is
// generated by tools/layout/object_schemas.py; the compiler supplies each member's offset, size and kind.
#include "gbtg/types.h"

#include <span>

namespace gbtg
{
struct ObjectSchema;

struct ObjectSchemaField
{
    const char* name;
    const char* note;
    u32 offset;
    u32 size; // All elements.
    u32 kind; // GbtgFieldKind; GBTG_FIELD_GROUP for a nested struct or an array of them.
    u32 count; // Elements; 1 for a scalar.
    const ObjectSchema* nested; // The element's struct for a group.
};

struct ObjectSchema
{
    const char* name;
    u32 size;
    std::span<const ObjectSchemaField> fields;
};

// Sorted by name.
std::span<const ObjectSchema* const> object_schemas();
const ObjectSchema* find_object_schema(const char* name);
// The struct a factory type's own object is laid out as, or nullptr when no named struct is known for the type. The
// caller walks the factory table's parents for the rest (types 2, 3, 8 and 9 are the actor, scene-control, strategy
// and body-state bases).
const ObjectSchema* object_schema_for_type(u32 type);
}
